Basic core functions 

Solver for Snell’s law 

(*Solve for the wave vector and electric field direction of the reflective / transmitive waves*)
Clear[solveSnell];
SetAttributes[solveSnell, HoldAll];
(*Inputs:; 
mat  -  the material;
wIn  -  the incident wave;
wOut1  -  the output (reflective or transmitive) wave 1; 
wOut2  -  the output (reflective or transmitive) wave 2; 
reflect  -  if True,  compute reflective wave; if False,  compute transmitive wave; 

Outputs:;
k and E vectors (only direction with normalized magnitude) for wOut1 and wOut2,  stored in the objects wOut1 and wOut2. ;
*)
solveSnell[mat_, wIn_, wOut1_, wOut2_, reflect_:False]:=Module[{\[Theta]t, n0, ux, uy, uz, L, R, V, W, \[CapitalLambda], C, \[Theta]i, m, QP0, 
	nfast, nslow, \[Theta]tfast, \[Theta]tslow, kfast, kslow, sol, \[Eta], v, pos, vfast, vslow, \[Theta]guess, \[CurlyEpsilon]P, \[CurlyEpsilon]L, resolu = 10^ - 8, crit0 = 10^ - 6}, 
	(*Find incident angle from wIn*)
	\[Theta]i = wIn[\[Theta]];
	(*Find refractive index of wIn; this is the refractive index of the prior material,  not the current one! ;*)
	n0 = (c0  / wIn[\[Omega]])wIn[k0]; 
	
	(*Determine whether to compute the \[Omega] or 2\[Omega] waves,  from the wOut*)
	If[Abs[wOut1[\[Omega]] - \[Omega]0]<= 10^ - 3, \[CurlyEpsilon]P = mat[\[CurlyEpsilon]\[Omega]P];\[CurlyEpsilon]L = mat[\[CurlyEpsilon]\[Omega]L];QP0 = mat[QP\[Omega]]];
	If[Abs[wOut1[\[Omega]] - 2\[Omega]0]<= 10^ - 3, \[CurlyEpsilon]P = mat[\[CurlyEpsilon]2\[Omega]P];\[CurlyEpsilon]L = mat[\[CurlyEpsilon]2\[Omega]L];QP0 = mat[QP2\[Omega]]];
	(*Follow the routine*)
	ux = Sin[\[Theta]t];  uy = 0.0;  uz = Cos[\[Theta]t];
	L = {{uy^2 + uz^2,  - ux * uy,  - ux * uz}, { - ux * uy, ux^2 + uz^2,  - uy * uz}, { - uz * ux,  - uz * uy, ux^2 + uy^2}};
	R = MatrixPower[\[CurlyEpsilon]P, 1 / 2].Transpose@QP0;(*Pay attention! My Q is the transpose of the Q defined in Chang's paper*)
	C = Inverse[R];\[CapitalLambda] = Transpose[C].L.C;
	V = (1 / 2)(\[CapitalLambda][[1, 1]] + \[CapitalLambda][[2, 2]] + \[CapitalLambda][[3, 3]]);
	W = \[CapitalLambda][[1, 1]]\[CapitalLambda][[2, 2]] + \[CapitalLambda][[1, 1]]\[CapitalLambda][[3, 3]] + \[CapitalLambda][[2, 2]]\[CapitalLambda][[3, 3]] - \[CapitalLambda][[3, 1]]\[CapitalLambda][[1, 3]] - \[CapitalLambda][[1, 2]]\[CapitalLambda][[2, 1]] - \[CapitalLambda][[2, 3]]\[CapitalLambda][[3, 2]];
	If[debug, Print["QP0,\[CurlyEpsilon]P,R,C,\[CapitalLambda],V,W", Simplify@{QP0, \[CurlyEpsilon]P, R, C, \[CapitalLambda], V, W}]];
	
	(*For aniso in general*)
	nfast = (*Chop@*)Simplify@Sqrt[(V - Sqrt[V^2 - W]) / W];
	nslow = (*Chop@*)Simplify@Sqrt[(V + Sqrt[V^2 - W]) / W];
	
	If[Element[Flatten@ Chop[\[CurlyEpsilon]P], Reals], 
		If[reflect, \[Theta]guess = Pi - \[Theta]i, \[Theta]guess = \[Theta]i];
		, 
		If[reflect, \[Theta]guess = Pi - \[Theta]i + 0.1I, \[Theta]guess = \[Theta]i + 0.1I];
	];
	
	Quiet@(sol = FindRoot[Sin[\[Theta]t]nfast== n0 Sin[\[Theta]i], {\[Theta]t, \[Theta]guess}]);
	\[Theta]tfast = (\[Theta]t/.sol);
	nfast = (nfast/.sol);
	
	Quiet@(sol = FindRoot[Sin[\[Theta]t]nslow== n0 Sin[\[Theta]i], {\[Theta]t, \[Theta]guess}]);
	\[Theta]tslow = (\[Theta]t/.sol);
	nslow = (nslow/.sol);
	
	If[debug, Print["\[Theta]fast and \[Theta]slow from Snell's law:\n", {\[Theta]tfast, \[Theta]tslow}]];
	If[debug, Print["nfast and nslow from Snell's law:\n", {nfast, nslow}]];
	
	If[Abs@Im[\[Theta]tfast]<=resolu, \[Theta]tfast = Re[\[Theta]tfast]];
	If[Abs@Im[\[Theta]tslow]<=resolu, \[Theta]tslow = Re[\[Theta]tslow]];
	If[Not[reflect] &&( Re@\[Theta]tfast>=Pi / 2||Re@\[Theta]tslow>=Pi / 2), Print["Error! \[Theta]t is obtuse!", "\[Theta]tfast = ", \[Theta]tfast, "\[Theta]tslow = ", \[Theta]tslow];Abort[]];
	If[reflect && (Re@\[Theta]tfast<=Pi / 2||Re@\[Theta]tslow<= Pi / 2), Print["Error! \[Theta]r is acute!", "\[Theta]tfast = ", \[Theta]tfast, "\[Theta]tslow = ", \[Theta]tslow];Abort[]];
	
	If[debug, Print["|kfast| and |kslow|: \n", {(nfast wOut1[\[Omega]] / c0), (nslow wOut2[\[Omega]] / c0)}]];
	kfast = (nfast wOut1[\[Omega]] / c0){Sin[\[Theta]tfast], 0, Cos[\[Theta]tfast]};
	kslow = (nslow wOut2[\[Omega]] / c0){Sin[\[Theta]tslow], 0, Cos[\[Theta]tslow]};
	wOut1[[Key[k]]] = Chop[kfast, crit0];
	wOut2[[Key[k]]] = Chop[kslow, crit0];
	wOut1[[Key[k0]]] = (nfast wOut1[\[Omega]] / c0);
	wOut2[[Key[k0]]] = (nslow wOut2[\[Omega]] / c0);
	wOut1[[Key[\[Theta]]]] = \[Theta]tfast;
	wOut2[[Key[\[Theta]]]] = \[Theta]tslow;
	
	If[Chop[\[Theta]tfast - \[Theta]tslow, resolu]==0 , 
		(*For Isotropic,  or  when two waves are identical in propagting direction*)
		If[debug, Print["Iso or quasi Iso\n"]];
		
		If[eigenStandard, 
			m = \[CapitalLambda]/.\[Theta]t-> \[Theta]tfast;
			If[HermitianMatrixQ[m], 
				{\[Eta], v} = Eigensystem[m, 2, Method->"Banded"]
				, 
				{\[Eta], v} = Eigensystem[m, 2]
			];
			v = Normalize/@(v.C\[Transpose]);
			If[debug, Print["Using standard eigensystem {\[Eta],v} for \[Theta]tfast\n", {\[Eta], v}]];
			, 
			m = {L, \[CurlyEpsilon]L}/.\[Theta]t-> \[Theta]tfast;
			{\[Eta], v} = Eigensystem[m, 2];
			If[debug, Print["Using generalized eigensystem {\[Eta],v} for \[Theta]tfast\n", {\[Eta], v}]];
		];
		
		vfast = Chop[v[[1]], crit0];
		vslow = Chop[v[[2]], crit0];
		If[debug, Print["vfast, vslow\n", {vfast,  vslow}]];
		wOut1[[Key[EE]]] = wOut1[EE]vfast;
		wOut2[[Key[EE]]] = wOut2[EE]vslow;
		, 
		If[debug, Print["Aniso\n"]];
		If[eigenStandard, 
			m = \[CapitalLambda]/.\[Theta]t-> \[Theta]tfast;
			If[HermitianMatrixQ[m], 
				{\[Eta], v} = Eigensystem[m, 2, Method->"Banded"]
				, 
				{\[Eta], v} = Eigensystem[m, 2]
			];
			v = Normalize/@(v.C\[Transpose]);
			If[debug, Print["Using standard eigensystem {\[Eta],v} for \[Theta]tfast\n", {\[Eta], v}]];
			, 
			m = {L, \[CurlyEpsilon]L}/.\[Theta]t-> \[Theta]tfast;
			{\[Eta], v} = Eigensystem[m, 2];
			If[debug, Print["Using generalized eigensystem {\[Eta],v} for \[Theta]tfast\n", {\[Eta], v}]];
		];
		
		vfast = Select[Thread[{\[Eta], v}], Abs[#[[1]] - 1 / nfast^2]<=resolu&][[1, 2]];
		vfast = Chop[vfast, crit0];
		wOut1[[Key[EE]]] = wOut1[EE]vfast;
		
		If[eigenStandard, 
			m = \[CapitalLambda]/.\[Theta]t-> \[Theta]tslow;
			If[HermitianMatrixQ[m], 
				({\[Eta], v} = Eigensystem[m, 2, Method->"Banded"])
				, 
				({\[Eta], v} = Eigensystem[m, 2])
			];
			v = Normalize/@(v.C\[Transpose]);
			If[debug, Print["Using standard eigensystem {\[Eta],v} for \[Theta]tslow\n", {\[Eta], v}]]
			, 
			m = {L, \[CurlyEpsilon]L}/.\[Theta]t-> \[Theta]tslow;
			{\[Eta], v} = Eigensystem[m, 2];
			If[debug, Print["Using generalized {\[Eta],v} for \[Theta]tslow\n", {\[Eta], v}]];
		];
		
		vslow = Select[Thread[{\[Eta], v}], Abs[#[[1]] - 1 / nslow^2]<=resolu&][[1, 2]];
		vslow = Chop[vslow, crit0];
		wOut2[[Key[EE]]] = wOut2[EE]vslow;
		If[debug, Print["vfast, vslow\n", {vfast,  vslow}]];
	];
]

Solver for Fresnel’s law 

(*Solve the electric field magnitude of the reflective / transmitive waves by boundary condition method*)
(*For single reflection on one surface *)
(*
Inputs:;
wIn  -  a list of incident waves;
wR  -  a list of reflective waves; 
wT  -  a list of transmitive waves; 
*)
ClearAll[solveFresnel];
SetAttributes[solveFresnel, HoldAll];
(*Generalized wIn,  wR,  wT with any numbers of waves*)
solveFresnel[wIn_List, wR_List, wT_List, unknowns_]:=Module[{getH, sol, equ, EMtop, EMbot, HMtop, HMbot, B, M}, 
	getH[wav_]:=Cross[Key[k]@wav, Key[EE]@wav] / (Key[\[Omega]]@wav \[Mu]0);
	
	EMtop = Total[(Key[EE]@#)&/@Flatten[{wIn, wR}]];
	EMbot = Total[(Key[EE]@#)&/@Flatten[wT]];
	HMtop = Total[(getH@#)&/@Flatten[{wIn, wR}]];
	HMbot = Total[(getH@#)&/@Flatten[wT]];
	
	If[flagLinearSolve, 
		equ = (*Simplify@*){
			EMtop[[1]] - EMbot[[1]] == 0, 
		HMtop[[1]] - HMbot[[1]] == 0, 
		EMtop[[2]] - EMbot[[2]] == 0, 
		HMtop[[2]] - HMbot[[2]] == 0};
		{B, M} = Normal@CoefficientArrays[equ, unknowns];
		sol = Thread[unknowns->LinearSolve[M, B]];
		, 
		equ = {
			EMtop[[1;;2]] == EMbot[[1;;2]], 
			HMtop[[1;;2]] == HMbot[[1;;2]]
		};
		equ = Flatten@Simplify@(Thread/@equ);
		
		Quiet@If[flagNSolve, 
			sol = NSolve[equ, unknowns]
			, 
			sol = Solve[equ, unknowns]
		];
		If[sol === {}, Print["sol is {} in solveFresnel! "];sol = Thread[{unknowns->ConstantArray[0., Length@unknowns]}], sol = sol[[1]]];
	];
	
	(*Return[sol];*)
	wR = wR/.sol;(*Only updated the E of waves in the List wR,  not H*)
	wT = wT/.sol;
]

(*Solve the electric field magnitude of the reflective / transmitive waves by boundary condition method*)
(*For reflection and transmission of nonlinear waves across arbitrary number of slabs *)
(*
Inputs:;
wAir  -  a list of waves from Air or into Air;
wF  -  a list of Forward waves; 
wB  -  a list of Backward waves;
wSub  -  a lits of  waves into Substrate (can be Air); 
nM  -  the number of media (layers) is obtained from the length of wF;  

Outpus:; 
the solved electric field vectors for wAir,  wF,  wB,  and wSub,  all stored in the corresponding objects of the lists ; 
*)
ClearAll[solveFresnelN];
SetAttributes[solveFresnelN, HoldAll];
solveFresnelN[wAir_, wMed_, wSub_, thickness_, unknowns_]:=Module[
	{sol = {}, i, equ = {}, equE, equH, nM, equTop, equBot, getH, nloop = 0, B, M}, 
	nM = Length[wMed];
	getH[wav_]:=Cross[Key[k]@wav, Key[EE]@wav] / (Key[\[Omega]]@wav \[Mu]0);
	(*contruct the boundary conditions*)
	(*the top surface*)
	equTop = {
		(Total[Key[EE]/@wAir][[1;;2]])==((Total[Key[EE]/@wMed[[1]]])[[1;;2]]), 
	(Total[getH/@wAir][[1;;2]])==((Total[getH/@wMed[[1]]])[[1;;2]])};
	AppendTo[equ, equTop];
	(*the multilayers*)
	For[i = 1, i<nM, i++, 
		equE = ((Total[(Exp[I(#[k].{0, 0, 1}thickness[[i]])](Key[EE]@#))&/@wMed[[i]]])[[1;;2]])== ((Total[Key[EE]/@wMed[[i + 1]]])[[1;;2]]);
		equH = ((Total[(Exp[I  (#[k].{0, 0, 1}thickness[[i]])](getH@#))&/@wMed[[i]]])[[1;;2]])== ((Total[getH/@wMed[[i + 1]]])[[1;;2]]);
		AppendTo[equ, {equE, equH}]
	];
	(*the bottom surface*)
	equBot = {
		((Total[(Exp[I  (#[k].{0, 0, 1}thickness[[nM]])](Key[EE]@#))&/@wMed[[nM]]])[[1;;2]]) == (Total[Key[EE]/@wSub][[1;;2]]), 
	((Total[(Exp[I  (#[k].{0, 0, 1}thickness[[nM]])](getH@#))&/@wMed[[nM]]])[[1;;2]]) == (Total[getH/@wSub][[1;;2]])};
	AppendTo[equ, equBot];
	equ = (*Chop@*)(*Simplify@*)Flatten[equ];
	equ = Flatten@(Thread/@equ);
	
	If[debug, Print["k of wMed\n", #[k]&/@wMed[[nM]]]];
	If[debug, Print["Here!!! equ\n", Flatten@(Thread/@equ)/.{\[CapitalDelta]\[Delta]->0}//Simplify//Chop//MatrixForm]];
	If[flagLinearSolve, 
		{B, M} = Normal@CoefficientArrays[equ, unknowns];
		sol = Thread[unknowns->LinearSolve[M, B]];
		, 
		Quiet@If[flagNSolve, 
			sol = NSolve[equ, unknowns], 
			sol = Solve[equ, unknowns]
		];
		If[Length@sol == 0, Print["sol is {} in solveFresnelN!"];sol = Thread[unknowns->ConstantArray[0., Length@unknowns]], 
		sol = sol[[1]]];
	];
	If[debug, Print["sol\n", sol//Simplify//MatrixForm]];
	wAir = wAir/.sol;
	wSub = wSub/.sol;
	wMed = wMed/.sol;
]

