ClearAll[computePNL];
(*self - explanatory*)
computePNL[dL_List, E1_List, E2_List, factor_:1]:=(factor)dL.({#1[[1]] #2[[1]], #1[[2]] #2[[2]], #1[[3]] #2[[3]], #1[[2]] #2[[3]] + #1[[3]] #2[[2]], #1[[1]] #2[[3]] + #1[[3]] #2[[1]], #1[[2]] #2[[1]] + #1[[1]] #2[[2]]}&@@{E1, E2});

ClearAll[solveInhom];
SetAttributes[solveInhom, HoldAll];
(*for single interface or slab case*)
solveInhom[mat_, wT1\[Omega]_, wT2\[Omega]_, wT12\[Omega]Inh_, wT22\[Omega]Inh_, wTmix2\[Omega]Inh_]:=Module[{w, phases, eT1\[Omega], eT2\[Omega], PNLT1, PNLT2, PNLmix, eT12\[Omega]Inh, eT22\[Omega]Inh, eTmix2\[Omega]Inh, lhs, rhs, equ, sol, unknowns, M, B}, 
	unknowns = {C11, C21, C31, C12, C22, C32, C13, C23, C33};
	If[mat[pg][[ - 1]] == 0, 
		(*No need to solve if the layer is linear material*)
		wT12\[Omega]Inh[EE] = {0., 0., 0.};
		wT22\[Omega]Inh[EE] = {0., 0., 0.};
		wTmix2\[Omega]Inh[EE] = {0., 0., 0.}
	];
	If[mat[pg][[ - 1]] == 1, 
		(* Define real space vector r and phases which contain ko,  keo,  and ko + keo *)
		w = wT1\[Omega][\[Omega]];
		phases = (*Chop/@*)<|
		T1\[Omega]->Exp[I(wT1\[Omega][\[Omega]] t - (*Re@*)wT1\[Omega][k].{x, y, z})], 
		T2\[Omega]->Exp[I(wT2\[Omega][\[Omega]] t - (*Re@*)wT2\[Omega][k].{x, y, z})], 
		T1-> Exp[I(wT12\[Omega]Inh[\[Omega]]t - (*Re@*)wT12\[Omega]Inh[k].{x, y, z})], 
		T2-> Exp[I(wT22\[Omega]Inh[\[Omega]] t - (*Re@*)wT22\[Omega]Inh[k].{x, y, z})], 
		mix-> Exp[I(wTmix2\[Omega]Inh[\[Omega]]t - (*Re@*)wTmix2\[Omega]Inh[k].{x, y, z})]|>;
		(* Compute PNL from \[Omega] waves; e is propagating electric field *)
		eT1\[Omega] = (*Chop@*)(wT1\[Omega][EE]phases[T1\[Omega]](*wT1\[Omega][phase]*));
		eT2\[Omega] = (*Chop@*)(wT2\[Omega][EE]phases[T2\[Omega]](*wT2\[Omega][phase]*));
		If[debug, Print["dL:\n", mat[dL]//MatrixForm]];
		PNLT1 = computePNL[mat[dL], eT1\[Omega], eT1\[Omega]];
		PNLT2 = computePNL[mat[dL], eT2\[Omega], eT2\[Omega]];
		PNLmix = computePNL[mat[dL], eT1\[Omega], eT2\[Omega], 2];(*need the  * 2 here*)
		
		(* Establish equations for solving inhomogeneous waves; e is propagating electric field *)
		(*Replace the phasor to preset ones for better match *)
		PNLT1 = PNLT1/.a_. * E^b_:>a phases[T1];
		PNLT2 = PNLT2/.a_. * E^b_:>a phases[T2];
		PNLmix = PNLmix/.a_. * E^b_:>a phases[mix];
		
		If[debug, Print["PNL:\n", {PNLT1, PNLT2, PNLmix}//Chop//Simplify]];
		{eT12\[Omega]Inh, eT22\[Omega]Inh, eTmix2\[Omega]Inh} = (*Chop@*){
			wT12\[Omega]Inh[EE]phases[T1](*wT12\[Omega]Inh[phase]*), 
			wT22\[Omega]Inh[EE]phases[T2](*wT22\[Omega]Inh[phase]*), 
			wTmix2\[Omega]Inh[EE]phases[mix](*wTmix2\[Omega]Inh[phase]*)};
		If[debug, Print["eT12\[Omega]Inh,eT22\[Omega]Inh,eTmix2\[Omega]Inh:\n", {eT12\[Omega]Inh, eT22\[Omega]Inh, eTmix2\[Omega]Inh}]];
		lhs = (*Chop@*)Curl[Curl[#, {x, y, z}], {x, y, z}]&/@{eT12\[Omega]Inh, eT22\[Omega]Inh, eTmix2\[Omega]Inh};
		rhs = (*Chop@*)MapThread[((2w)^2\[Mu]0 \[CurlyEpsilon]0 (mat[\[CurlyEpsilon]2\[Omega]L].#1 + #2))&, {{eT12\[Omega]Inh, eT22\[Omega]Inh, eTmix2\[Omega]Inh}, {PNLT1, PNLT2, PNLmix}}];
		If[debug, Print["lhs:\n", lhs//MatrixForm]];
		If[debug, Print["rhs:\n", rhs//MatrixForm]];
		equ = (*Chop@*){
			Coefficient[lhs[[1]], phases[T1]] == Coefficient[rhs[[1]], phases[T1]], 
			Coefficient[lhs[[2]], phases[T2]] == Coefficient[rhs[[2]], phases[T2]], 
			Coefficient[lhs[[3]], phases[mix]] == Coefficient[rhs[[3]], phases[mix]]
		};
		If[debug, Print["equations for solving Cij:\n", Simplify@(Thread/@equ)]];
		(*Check in PNL need to be taken out*)
		If[flagLinearSolve, 
			{B, M} = Normal@CoefficientArrays[equ, unknowns];
			sol = Thread[unknowns->LinearSolve[M, B]];
			, 
			Quiet@If[flagNSolve, 
			sol = NSolve[Flatten@(Thread/@equ), unknowns(*, Method->Reduce*)], 
			sol = Solve[Flatten@(Thread/@equ), unknowns(*, Method->Reduce*)]];
		];
		If[debug, Print["C_ij: \n", 
		(ArrayReshape[unknowns, {3, 3}]/.sol)//Simplify//Transpose//MatrixForm]];
		If[Length@sol == 0, Print["Solution is empty for inhomogeneous 2\[Omega] wave"];sol = Thread[unknowns->ConstantArray[0., 9]];];
		wT12\[Omega]Inh[EE] = wT12\[Omega]Inh[EE]/.sol[[1]];
		wT22\[Omega]Inh[EE] = wT22\[Omega]Inh[EE]/.sol[[1]];
		wTmix2\[Omega]Inh[EE] = wTmix2\[Omega]Inh[EE]/.sol[[1]];
	];
	(*Return[{PNLT1, PNLT2, PNLmix}];*)
]

(*for general case*)
solveInhom[mat_, wHom_, wInhom_]:=Module[{w, phases, wF1, wF2, wB1, wB2, 
	wInhF1F1, wInhF2F2, wInhF1F2, wInhB1B1, wInhB2B2, wInhB1B2, wInhF1B2, wInhF2B1, wInhF1B1, wInhF2B2, 
	PNLF1F1, PNLF2F2, PNLF1F2, PNLB1B1, PNLB2B2, PNLB1B2, PNLF1B2, PNLF2B1, PNLF1B1, PNLF2B2, 
	eF1, eF2, eB1, eB2, 
	eInhF1F1, eInhF2F2, eInhF1F2, eInhB1B1, eInhB2B2, eInhB1B2, eInhF1B2, eInhF2B1, eInhF1B1, eInhF2B2, 
	lhs, rhs, equ, sol, unknowns, M, B}, 
	unknowns = Partition[{C11, C21, C31, C12, C22, C32, C13, C23, C33, C14, C24, C34, C15, C25, C35, C16, C26, C36, C17, C27, C37, C18, C28, C38, C19, C29, C39, C110, C210, C310}, 3];
	If[mat[pg][[ - 1]] == 0, 
		(*No need to solve if the layer is linear material*)
		sol = Thread[(Flatten@unknowns)->ConstantArray[0., 30]];
		wInhom = wInhom/.sol;
	];
	If[mat[pg][[ - 1]] == 1, 
		{wF1, wF2, wB1, wB2} = wHom;
		w = wF1[\[Omega]];
		{wInhF1F1, wInhF2F2, wInhF1F2, wInhB1B1, wInhB2B2, wInhB1B2, wInhF1B1, wInhF2B2, wInhF1B2, wInhF2B1} = wInhom;
		phases = (*Chop/@*)<|
		homF1->Exp[I((wF1[\[Omega]]) t - (*Re@*)wF1[k].{x, y, z})], 
		homF2->Exp[I((wF2[\[Omega]]) t - (*Re@*)wF2[k].{x, y, z})], 
		homB1->Exp[I((wB1[\[Omega]]) t - (*Re@*)wB1[k].{x, y, z})], 
		homB2->Exp[I((wB2[\[Omega]]) t - (*Re@*)wB2[k].{x, y, z})], 
		inhomF1F1-> Exp[I(wInhF1F1[\[Omega]]t - (*Re@*)wInhF1F1[k].{x, y, z})], 
		inhomF2F2-> Exp[I(wInhF2F2[\[Omega]]t - (*Re@*)wInhF2F2[k].{x, y, z})], 
		inhomF1F2-> Exp[I(wInhF1F2[\[Omega]]t - (*Re@*)wInhF1F2[k].{x, y, z})], 
		inhomB1B1-> Exp[I(wInhB1B1[\[Omega]]t - (*Re@*)wInhB1B1[k].{x, y, z})], 
		inhomB2B2-> Exp[I(wInhB2B2[\[Omega]]t - (*Re@*)wInhB2B2[k].{x, y, z})], 
		inhomB1B2-> Exp[I(wInhB1B2[\[Omega]]t - (*Re@*)wInhB1B2[k].{x, y, z})], 
		inhomF1B1-> Exp[I(wInhF1B1[\[Omega]]t - (*Re@*)wInhF1B1[k].{x, y, z})], 
		inhomF2B2-> Exp[I(wInhF2B2[\[Omega]]t - (*Re@*)wInhF2B2[k].{x, y, z})], 
		inhomF1B2-> Exp[I(wInhF1B2[\[Omega]]t - (*Re@*)wInhF1B2[k].{x, y, z})], 
		inhomF2B1-> Exp[I(wInhF2B1[\[Omega]]t - (*Re@*)wInhF2B1[k].{x, y, z})]
		|>;
		(* Compute PNL from \[Omega] waves; e is propagating electric field *)
		eF1 = (*Chop@*)(wF1[EE]phases[homF1]);
		eF2 = (*Chop@*)(wF2[EE]phases[homF2]);
		eB1 = (*Chop@*)(wB1[EE]phases[homB1]);
		eB2 = (*Chop@*)(wB2[EE]phases[homB2]);
		
		If[debug, Print["dL:\n", mat[dL]//MatrixForm]];
		PNLF1F1 =  computePNL[mat[dL], eF1, eF1];
		PNLF2F2 =  computePNL[mat[dL], eF2, eF2];
		PNLF1F2 =  computePNL[mat[dL], eF1, eF2, 2];
		PNLB1B1 =  computePNL[mat[dL], eB1, eB1];
		PNLB2B2 =  computePNL[mat[dL], eB2, eB2];
		PNLB1B2 =  computePNL[mat[dL], eB1, eB2, 2];
		PNLF1B1 =  computePNL[mat[dL], eF1, eB1, 2];
		PNLF2B2 =  computePNL[mat[dL], eF2, eB2, 2];
		PNLF1B2 =  computePNL[mat[dL], eF1, eB2, 2];
		PNLF2B1 =  computePNL[mat[dL], eF2, eB1, 2];
		
		(*Replace the phasor to preset ones for better match *)
		PNLF1F1 = PNLF1F1/.a_. * E^b_:>a phases[inhomF1F1];
		PNLF2F2 = PNLF2F2/.a_. * E^b_:>a phases[inhomF2F2];
		PNLF1F2 = PNLF1F2/.a_. * E^b_:>a phases[inhomF1F2];
		PNLB1B1 = PNLB1B1/.a_. * E^b_:>a phases[inhomB1B1];
		PNLB2B2 = PNLB2B2/.a_. * E^b_:>a phases[inhomB2B2];
		PNLB1B2 = PNLB1B2/.a_. * E^b_:>a phases[inhomB1B2];
		PNLF1B1 = PNLF1B1/.a_. * E^b_:>a phases[inhomF1B1];
		PNLF2B2 = PNLF2B2/.a_. * E^b_:>a phases[inhomF2B2];
		PNLF1B2 = PNLF1B2/.a_. * E^b_:>a phases[inhomF1B2];
		PNLF2B1 = PNLF2B1/.a_. * E^b_:>a phases[inhomF2B1];
		
		If[debug, Print["PNLs:\n", {PNLF1F1, PNLF2F2, PNLF1F2, PNLB1B1, PNLB2B2, PNLB1B2, PNLF1B1, PNLF2B2, PNLF1B2, PNLF2B1}//Simplify//Chop//MatrixForm]];
		
		{eInhF1F1, eInhF2F2, eInhF1F2, eInhB1B1, eInhB2B2, eInhB1B2, eInhF1B1, eInhF2B2, eInhF1B2, eInhF2B1} =  {
			wInhF1F1[EE]phases[inhomF1F1], 
		wInhF2F2[EE]phases[inhomF2F2], 
		wInhF1F2[EE]phases[inhomF1F2], 
		wInhB1B1[EE]phases[inhomB1B1], 
		wInhB2B2[EE]phases[inhomB2B2], 
		wInhB1B2[EE]phases[inhomB1B2], 
		wInhF1B1[EE]phases[inhomF1B1], 
		wInhF2B2[EE]phases[inhomF2B2], 
		wInhF1B2[EE]phases[inhomF1B2], 
		wInhF2B1[EE]phases[inhomF2B1]};
		
		If[debug, Print["eInhF1F1,eInhF2F2,eInhF1F2,eInhB1B1,eInhB2B2,eInhB1B2,eInhF1B1,eInhF2B2,eInhF1B2,eInhF2B1:\n", 
		{eInhF1F1, eInhF2F2, eInhF1F2, eInhB1B1, eInhB2B2, eInhB1B2, eInhF1B1, eInhF2B2, eInhF1B2, eInhF2B1}//Simplify]];
		
		lhs =  Curl[Curl[#, {x, y, z}], {x, y, z}]&/@{eInhF1F1, eInhF2F2, eInhF1F2, eInhB1B1, eInhB2B2, eInhB1B2, eInhF1B1, eInhF2B2, eInhF1B2, eInhF2B1};
		rhs =  MapThread[((2w)^2\[Mu]0 \[CurlyEpsilon]0 (mat[\[CurlyEpsilon]2\[Omega]L].#1 + #2))&, {{eInhF1F1, eInhF2F2, eInhF1F2, eInhB1B1, eInhB2B2, eInhB1B2, eInhF1B1, eInhF2B2, eInhF1B2, eInhF2B1}, {PNLF1F1, PNLF2F2, PNLF1F2, PNLB1B1, PNLB2B2, PNLB1B2, PNLF1B1, PNLF2B2, PNLF1B2, PNLF2B1}}];
		
		If[debug, Print["lhs:\n", lhs//MatrixForm]];
		If[debug, Print["rhs:\n", rhs//MatrixForm]];
		equ = (*Chop@*){
			Coefficient[lhs[[1]], phases[inhomF1F1]] == Coefficient[rhs[[1]], phases[inhomF1F1]], 
			Coefficient[lhs[[2]], phases[inhomF2F2]] == Coefficient[rhs[[2]], phases[inhomF2F2]], 
			Coefficient[lhs[[3]], phases[inhomF1F2]] == Coefficient[rhs[[3]], phases[inhomF1F2]], 
			Coefficient[lhs[[4]], phases[inhomB1B1]] == Coefficient[rhs[[4]], phases[inhomB1B1]], 
			Coefficient[lhs[[5]], phases[inhomB2B2]] == Coefficient[rhs[[5]], phases[inhomB2B2]], 
			Coefficient[lhs[[6]], phases[inhomB1B2]] == Coefficient[rhs[[6]], phases[inhomB1B2]], 
			Coefficient[lhs[[7]], phases[inhomF1B1]] == Coefficient[rhs[[7]], phases[inhomF1B1]], 
			Coefficient[lhs[[8]], phases[inhomF2B2]] == Coefficient[rhs[[8]], phases[inhomF2B2]], 
			Coefficient[lhs[[9]], phases[inhomF1B2]] == Coefficient[rhs[[9]], phases[inhomF1B2]], 
			Coefficient[lhs[[10]], phases[inhomF2B1]] == Coefficient[rhs[[10]], phases[inhomF2B1]]
		};
		If[debug, Print["equations for solving Cij:\n", equout = equ;MatrixForm@(*Chop@*)Simplify@(equ(*/.{\[CapitalDelta]\[Delta]->0}*))]];
		(*Check in PNL need to be taken out*)
		
		If[flagBackward&&flagStandingWave&&(!flagJK)&&(!flagHH), 
			Quiet@If[flagNSolve, 
				sol = Flatten[NSolve[Simplify@Flatten@equ[[#]], unknowns[[#]]]&/@Range[10]];
				, 
				sol = Flatten[Solve[Simplify@Flatten@equ[[#]], unknowns[[#]]]&/@Range[10]];
			]
			, 
			If[flagBackward&&(!flagStandingWave)&&(!flagJK)&&(!flagHH), 
				Quiet@If[flagNSolve, 
					sol = Flatten[NSolve[Simplify@Flatten@equ[[#]], unknowns[[#]]]&/@Range[6]];
					, 
					sol = Flatten[Solve[Simplify@Flatten@equ[[#]], unknowns[[#]]]&/@Range[6]];
				];
				sol = Join[sol, Thread[Flatten[unknowns[[7;;10]]]->ConstantArray[0, 12]]];
				, 
				If[!(flagBackward)||flagHH||flagJK, 
					Quiet@If[flagNSolve, 
						sol = Flatten[NSolve[Simplify@Flatten@equ[[#]], unknowns[[#]]]&/@Range[3]];
						, 
						sol = Flatten[Solve[Simplify@Flatten@equ[[#]], unknowns[[#]]]&/@Range[3]];
					];
					sol = Join[sol, Thread[Flatten[unknowns[[4;;10]]]->ConstantArray[0, 21]]];
				]
			]
		];
		If[debug, Print["C_ij: \n", 
		(unknowns/.sol)//Simplify//Chop//MatrixForm]];
		If[Length@sol == 0, Print["Solution 1 is empty for inhomogeneous 2\[Omega] wave! Aborted!"];sol = Thread[(Flatten@unknowns)->ConstantArray[0, 30]];Abort[]];
		wInhom = wInhom/.Flatten@sol;
	];
]

Combined core functions 

Single interface 

(*For single reflection linear wave*)
(*
Inputs: ;
m1  -  the first material where incident wave comes from; may or may not to be Air; 
m2  -  the second material;
Outputs: ;
wR1  -  the reflective wave 1;
wR2  -  the reflective wave 2;
wT1  -  the transmitive wave 1;
wT2  -  the transmitive wave 2;
*)
ClearAll[f1L];
SetAttributes[f1L, HoldAll];
f1L[m1_, m2_, wInc_, solFresnel_:True]:=Module[{w, wR1, wR2, wT2, wT1}, 
	If[!(ValueQ[m1]&&ValueQ[m2]&&ValueQ[wInc]), Print["Unvalued arguments detected when calling the function! Abort!"];Abort[];];
	w = wInc[\[Omega]];
	(*reflection at top*)
	wR1 = setWave[{w, kR1, k0R1, \[Theta]R1, ER1}];
	wR2 = setWave[{w, kR2, k0R2, \[Theta]R2, ER2}];
	wT1 = setWave[{w, kT1, k0T1, \[Theta]T1, ET1}];
	wT2 = setWave[{w, kT2, k0T2, \[Theta]T2, ET2}];
	solveSnell[m2, wInc, wT1, wT2];
	solveSnell[m1, wInc, wR1, wR2, True];(*backward*)
	If[solFresnel, solveFresnel[{wInc}, {wR1, wR2}, {wT1, wT2}]];
	
	{{wR1, wR2}, {wT1, wT2}}
]

(*For single reflection nonlinear wave*)
(*
Inputs: ;
m1  -  the first material where incident wave comes from; may or may not to be Air; 
m2  -  the second material;
Outputs: ;
wR1\[Omega]  -  the reflective wave 1 at \[Omega] frequency;
wR2\[Omega]  -  the reflective wave 2 at \[Omega] frequency;
wT1\[Omega]  -  the transmitive wave 1 at \[Omega] frequency;
wT2\[Omega]  -  the transmitive wave 2 at \[Omega] frequency;
wR12\[Omega]Hom  -  the reflective wave 1 at 2\[Omega] frequency,  homogeneous part;
wR22\[Omega]Hom  -  the reflective wave 2 at 2\[Omega] frequency,  homogeneous part;
wT12\[Omega]Hom  -  the transmitive wave 1 at 2\[Omega] frequency,  homogeneous part;
wT22\[Omega]Hom  -  the transmitive wave 2 at 2\[Omega] frequency,  homogeneous part;
wT12\[Omega]Inhom  -  the transmitive wave 1 at 2\[Omega] frequency,  inhomogeneous part;
wT22\[Omega]Inhom  -  the transmitive wave 2 at 2\[Omega] frequency,  inhomogeneous part;
*)
ClearAll[f1NL];(*not called; just for backup*)
SetAttributes[f1NL, HoldAll];
f1NL[m1_, m2_, wInc_]:=Module[{w, wR1\[Omega], wR2\[Omega], wT1\[Omega], wT2\[Omega], wR12\[Omega]Hom, wR22\[Omega]Hom, wT12\[Omega]Hom, wT22\[Omega]Hom, wT12\[Omega]Inh, wT22\[Omega]Inh, wTmix2\[Omega]Inh, sol, equ, unknowns, sollinear, \[Theta]tmp}, 
	If[!(ValueQ[m1]&&ValueQ[m2]&&ValueQ[wInc]), Print["Unvalued arguments detected when calling the function! Abort!"];Abort[];];
	w = wInc[\[Omega]];
	(* Obtain the two transmitted \[Omega] waves by f1L *)
	sollinear = f1L[m1, m2, wInc, True];
	{wR1\[Omega], wR2\[Omega]} = sollinear[[1]];
	{wT1\[Omega], wT2\[Omega]} = sollinear[[2]];
	If[debug, 
		Print["wT1\[Omega]: \n", wT1\[Omega] //MatrixForm];
		Print["wT2\[Omega]: \n", wT2\[Omega]//MatrixForm];
	];
	(* Obtain the two transmitted and two reflective 2\[Omega] waves by solveSnell *)
	wT12\[Omega]Hom = setWave@{2w, kT12\[Omega], k0T12\[Omega], \[Theta]T12\[Omega], ET12\[Omega]};
	wT22\[Omega]Hom = setWave@{2w, kT22\[Omega], k0T22\[Omega], \[Theta]T22\[Omega], ET22\[Omega]};
	wR12\[Omega]Hom = setWave@{2w, kR12\[Omega], k0R12\[Omega], \[Theta]R12\[Omega], ER12\[Omega]};
	wR22\[Omega]Hom = setWave@{2w, kR22\[Omega], k0R22\[Omega], \[Theta]R22\[Omega], ER22\[Omega]};
	solveSnell[m2, wInc, wT12\[Omega]Hom, wT22\[Omega]Hom];
	solveSnell[m1, wInc, wR12\[Omega]Hom, wR22\[Omega]Hom, True];
	(* Setup the three inhomogeneous 2\[Omega] waves whose magnitude to be determined by Cij,  which is solved within solveInhom *)
	wT12\[Omega]Inh = setWave@{2w, 2wT1\[Omega][k], 2wT1\[Omega][k0], wT1\[Omega][\[Theta]], {C11, C21, C31}};
	wT22\[Omega]Inh = setWave@{2w, 2wT2\[Omega][k], 2wT2\[Omega][k0], wT2\[Omega][\[Theta]], {C12, C22, C32}};
	\[Theta]tmp = VectorAngle[(wT1\[Omega][k] + wT2\[Omega][k]) / (wT1\[Omega][k0] + wT2\[Omega][k0]), {0, 0, 1}];
	wTmix2\[Omega]Inh = setWave@{2w, wT1\[Omega][k] + wT2\[Omega][k], wT1\[Omega][k0] + wT2\[Omega][k0], \[Theta]tmp, {C13, C23, C33}};
	solveInhom[m2, wT1\[Omega], wT2\[Omega], wT12\[Omega]Inh, wT22\[Omega]Inh, wTmix2\[Omega]Inh];
	If[debug, 
		Print["wT12\[Omega]Inh: \n", wT12\[Omega]Inh //MatrixForm];
		Print["wT22\[Omega]Inh: \n", wT22\[Omega]Inh//MatrixForm];
		Print["wTmix2\[Omega]Inh: \n", wTmix2\[Omega]Inh//MatrixForm]
	];
	
	unknowns = Key[EE]/@{wR12\[Omega]Hom, wR22\[Omega]Hom, wT12\[Omega]Hom, wT22\[Omega]Hom};
	unknowns = DeleteDuplicates@Cases[unknowns, _Symbol, Infinity];
	solveFresnel[{}, {wR12\[Omega]Hom, wR22\[Omega]Hom}, {wT12\[Omega]Hom, wT22\[Omega]Hom, wT12\[Omega]Inh, wT22\[Omega]Inh, wTmix2\[Omega]Inh}, unknowns];
	(* Return solved 2\[Omega] wavs*)
	{sollinear, {{wR12\[Omega]Hom, wR22\[Omega]Hom}, {wT12\[Omega]Hom, wT22\[Omega]Hom}, {wT12\[Omega]Inh, wT22\[Omega]Inh, wTmix2\[Omega]Inh}}}
]

Multilayers

(*
For solving linear waves of any number of layers; the number of layer is the length of the list mAll; 

Inputs: ; 
m0  -  material for the incident wave; 
mAll  -  a list of N materials where N can be any integer >=2; 
mSub  -  material at the bottom; 
wInc  =  the incident wave; 
phaseChange  -  a list of thickness {{0, 0, h1}, {0, 0, h2}, ..., {0, 0, hN}} for the layers ;

Outputs: ;
{wR1, wR2}  -  the two reflective waves; 
{wT1, wT2}  -  the two transmitive waves; 
wB  -  a list of all Backward waves with \[Omega] frequency inside the layers ;
wF  -  a list of all Forward waves with \[Omega] frequency inside the layers ;
*)
ClearAll[f4L];
SetAttributes[f4L, HoldAll];
f4L[mAll_, wInc_, iterative_:False]:=Module[
	{m0, mSub, nM, w, wF1 = {}, wF2 = {}, wB1 = {}, wB2 = {}, wR1, wR2, wT1, wT2, kF1 = {}, kF2 = {}, EF1 = {}, EF2 = {}, unknowns, sol, equ, meds, wavs, i, wF, wB, thickness, wMed, wF1tmp, wF2tmp, wB1tmp, wB2tmp, wRs, wRp, wTs, wTp}, 
	If[!(ValueQ[mAll]&&ValueQ[wInc]), Print["Unvalued arguments detected when calling the function! Abort!"];Abort[];];
	w = wInc[\[Omega]];
	m0 = mAll[[1]];
	mSub = mAll[[ - 1]];
	nM = Length[mAll] - 2;
	(*Setup wave names*)
	For[i = 1, i<=nM, i++, 
		AppendTo[wF1, setWave@{w, ToExpression[Symbol["kF1"<>ToString[i]]], ToExpression[Symbol["k0F1"<>ToString[i]]], ToExpression[Symbol["\[Theta]F1"<>ToString[i]]], ToExpression[Symbol["EF1"<>ToString[i]]]}];
		AppendTo[wF2, setWave@{w, ToExpression[Symbol["kF2"<>ToString[i]]], ToExpression[Symbol["k0F2"<>ToString[i]]], ToExpression[Symbol["\[Theta]F2"<>ToString[i]]], ToExpression[Symbol["EF2"<>ToString[i]]]}];AppendTo[wB1, setWave@{w, ToExpression[Symbol["kB1"<>ToString[i]]], ToExpression[Symbol["k0B1"<>ToString[i]]], ToExpression[Symbol["\[Theta]B1"<>ToString[i]]], ToExpression[Symbol["EB1"<>ToString[i]]]}];
		AppendTo[wB2, setWave@{w, ToExpression[Symbol["kB2"<>ToString[i]]], ToExpression[Symbol["k0B2"<>ToString[i]]], ToExpression[Symbol["\[Theta]B2"<>ToString[i]]], ToExpression[Symbol["EB2"<>ToString[i]]]}]
	];
	wR1 = setWave[{w, kR1, k0R1, \[Theta]R1, ER1}];
	wR2 = setWave[{w, kR2, k0R2, \[Theta]R2, ER2}];
	wT1 = setWave[{w, kT1, k0T1, \[Theta]T1, ET1}];
	wT2 = setWave[{w, kT2, k0T2, \[Theta]T2, ET2}];
	
	(*Solve wave angles by Snell's law for each layer*)
	For[i = 1, i<=nM, i++, 
		solveSnell[mAll[[i + 1]], wInc, wF1[[i]], wF2[[i]]];
		solveSnell[mAll[[i + 1]], wF1[[i]], wB1[[i]], wB2[[i]], True];
	];
	solveSnell[mSub, wInc, wT1, wT2];(*transmission*)
	solveSnell[m0, wInc, wR1, wR2, True];(*reflection*)
	
	(*Store Forward and Backward waves in lists*)
	wF = Thread[{wF1, wF2}];
	wB = Thread[{wB1, wB2}];
	wMed = Flatten/@Thread[{wF, wB}];
	
	thickness = Key[h]/@mAll[[2;; - 2]];
	
	If[iterative, 
		(*Solve layer by layer*)
		unknowns = Key[EE]/@{wR1, wR2, wF1[[1]], wF2[[1]]};
		unknowns = DeleteDuplicates@Cases[unknowns, _Symbol, Infinity];
		solveFresnel[{wInc}, {wR1, wR2}, {wF1[[1]], wF2[[1]]}, unknowns];(*top*)
		wF1tmp = wF1[[1]];
		wF1tmp[EE] = wF1[[1]][EE] Exp[I wF1[[1]][k].({0, 0, 1}thickness[[1]])];
		wF2tmp = wF2[[1]];
		wF2tmp[EE] = wF2[[1]][EE] Exp[I wF2[[1]][k].({0, 0, 1}thickness[[1]])];
		wB1tmp = wB1[[1]];
		wB1tmp[EE] = wB1[[1]][EE] Exp[I wB1[[1]][k].({0, 0, 1}thickness[[1]])];
		wB2tmp = wB2[[1]];
		wB2tmp[EE] = wB2[[1]][EE] Exp[I wB2[[1]][k].({0, 0, 1}thickness[[1]])];
		If[flagHH, 
			wF1[[1]] = wF1tmp;
			wF2[[1]] = wF2tmp;
			(*wB1[[1]] = wB1tmp;
			wB2[[1]] = wB2tmp;*)
		];
		
		For[i = 1, i<nM, i++, (*middle*)
			unknowns = Key[EE]/@{wB1[[i]], wB2[[i]], wF1[[i + 1]], wF2[[i + 1]]};
			unknowns = DeleteDuplicates@Cases[unknowns, _Symbol, Infinity];
			solveFresnel[{wF1tmp, wF2tmp}, {wB1[[i]], wB2[[i]]}, {wF1[[i + 1]], wF2[[i + 1]]}, unknowns];
			wF1tmp = wF1[[i + 1]];
			wF1tmp[EE] = wF1[[i + 1]][EE] Exp[I wF1[[i + 1]][k].({0, 0, 1}thickness[[i + 1]])];
			wF2tmp = wF2[[i + 1]];
			wF2tmp[EE] = wF2[[i + 1]][EE] Exp[I wF2[[i + 1]][k].({0, 0, 1}thickness[[i + 1]])];
			wB1tmp = wB1[[i + 1]];
			wB1tmp[EE] = wB1[[i + 1]][EE] Exp[I wB1[[i + 1]][k].({0, 0, 1}thickness[[i + 1]])];
			wB2tmp = wB2[[i + 1]];
			wB2tmp[EE] = wB2[[i + 1]][EE] Exp[I wB2[[i + 1]][k].({0, 0, 1}thickness[[i + 1]])];
			If[flagHH, 
				wF1[[i + 1]] = wF1tmp;
				wF2[[i + 1]] = wF2tmp;
				(*wB1[[i + 1]] = wB1tmp;
				wB2[[i + 1]] = wB2tmp;*)
			];
		];
		
		unknowns = Key[EE]/@{wB1[[nM]], wB2[[nM]], wT1, wT2};
		unknowns = DeleteDuplicates@Cases[unknowns, _Symbol, Infinity];
		solveFresnel[{wF1tmp, wF2tmp}, {wB1[[nM]], wB2[[nM]]}, {wT1, wT2}, unknowns];(*bottom*)
		wF = Thread[{wF1, wF2}];
		wB = Thread[{wB1, wB2}];
		, 
		(*Solve all waves at once*)
		unknowns = Join[Key[EE]/@{wR1, wR2}, Key[EE]/@Flatten@{wF, wB}, Key[EE]/@{wT1, wT2}];
		unknowns = DeleteDuplicates@Cases[unknowns, _Symbol, Infinity];
		solveFresnelN[{wInc, wR1, wR2}, wMed, {wT1, wT2}, thickness, unknowns];
		wF = wMed[[All, 1;;2]];
		wB = wMed[[All, 3;;4]];
	];
	(*distinguish s and p from R1 and R2, T1 and T2*)
	(*no need to distinguish them for B and F waves cause they don't have to be s and p*)
	wRs = Cases[{wR1, wR2}, <|__, EE->{0, Except[0], 0}|>][[1]];
	wRp = DeleteCases[{wR1, wR2}, <|__, EE->{0, Except[0], 0}|>][[1]];
	wTs = Cases[{wT1, wT2}, <|__, EE->{0, Except[0], 0}|>][[1]];
	wTp = DeleteCases[{wT1, wT2}, <|__, EE->{0, Except[0], 0}|>][[1]];
	
	{{wRp, wRs}, {wTp, wTs}, wB, wF}
];

ClearAll[f4NL];
SetAttributes[f4NL, HoldAll];
f4NL[mAll_, wInc_, iterative_:False]:=Module[
	{m0, mSub, nM, w, kF1 = {}, kF2 = {}, EF1 = {}, EF2 = {}, 
	wF1 = {}, wF2 = {}, wB1 = {}, wB2 = {}, wF1F1Inh = {}, wF2F2Inh = {}, wF1F2Inh = {}, wB1B1Inh = {}, wB2B2Inh = {}, wB1B2Inh = {}, wF1B2Inh = {}, wF2B1Inh = {}, wF1B1Inh = {}, wF2B2Inh = {}, wInh, wRs, wRp, wTs, wTp, 
	wFHomo, wBHomo, wFInh, wBInh, wSInh, wR1, wR2, wT1, wT2, unknowns, sol, equ, meds, wavs, i, wMed, wF1tmp, wF2tmp, wB1tmp, wB2tmp, 
	sollinear, wFtmp, wBtmp, wF1F1Inhtmp, wF2F2Inhtmp, wF1F2Inhtmp, wB1B1Inhtmp, wB2B2Inhtmp, wB1B2Inhtmp, wF1B1Inhtmp, wF1B2Inhtmp, wF2B1Inhtmp, wF2B2Inhtmp, thickness, \[Theta]tmp}, 
	
	If[!((*ValueQ[m0]&&*)ValueQ[mAll](*&&ValueQ[mSub]*)&&ValueQ[wInc]), Print["Unvalued arguments detected when calling the function! Abort!"];Abort[];];
	w = wInc[\[Omega]];
	m0 = mAll[[1]];
	mSub = mAll[[ - 1]];
	nM = Length[mAll] - 2;
	
	(*Setup wave names*)
	For[i = 1, i<=nM, i++, 
		AppendTo[wF1, setWave@{2w, ToExpression[Symbol["kF1"<>ToString[i]]], ToExpression[Symbol["k0F1"<>ToString[i]]], ToExpression[Symbol["\[Theta]F1"<>ToString[i]]], ToExpression[Symbol["EF1"<>ToString[i]]]}];
		AppendTo[wF2, setWave@{2w, ToExpression[Symbol["kF2"<>ToString[i]]], ToExpression[Symbol["k0F2"<>ToString[i]]], ToExpression[Symbol["\[Theta]F2"<>ToString[i]]], ToExpression[Symbol["EF2"<>ToString[i]]]}];AppendTo[wB1, setWave@{2w, ToExpression[Symbol["kB1"<>ToString[i]]], ToExpression[Symbol["k0B1"<>ToString[i]]], ToExpression[Symbol["\[Theta]B1"<>ToString[i]]], ToExpression[Symbol["EB1"<>ToString[i]]]}];
		AppendTo[wB2, setWave@{2w, ToExpression[Symbol["kB2"<>ToString[i]]], ToExpression[Symbol["k0B2"<>ToString[i]]], ToExpression[Symbol["\[Theta]B2"<>ToString[i]]], ToExpression[Symbol["EB2"<>ToString[i]]]}]
	];
	wR1 = setWave[{2w, kR1, k0R1, \[Theta]R1, ER1}];
	wR2 = setWave[{2w, kR2, k0R2, \[Theta]R2, ER2}];
	wT1 = setWave[{2w, kT1, k0T1, \[Theta]T1, ET1}];
	wT2 = setWave[{2w, kT2, k0T2, \[Theta]T2, ET2}];
	
	(*Solve wave angles by Snell's law for each layer*)
	For[i = 1, i<=nM, i++, 
		solveSnell[mAll[[i + 1]], wInc, wF1[[i]], wF2[[i]]];
		solveSnell[mAll[[i + 1]], wF1[[i]], wB1[[i]], wB2[[i]], True];
	];
	solveSnell[mSub, wInc, wT1, wT2];(*transmission*)
	solveSnell[m0, wInc, wR1, wR2, True];(*reflection*)
	
	(*solve the linear problem*)
	sollinear = f4L[mAll, wInc, iterative];
	
	(*Store the w waves in tmp*)
	wBtmp = sollinear[[3]];
	wFtmp = sollinear[[4]];
	
	(*Setup inhomo wave names*)
	For[i = 1, i<=nM, i++, 
		wF1F1Inhtmp = setWave@{2w, 2wFtmp[[i, 1]][k], 2wFtmp[[i, 1]][k0], wFtmp[[i, 1]][\[Theta]], {C11, C21, C31}};
		wF2F2Inhtmp = setWave@{2w, 2wFtmp[[i, 2]][k], 2wFtmp[[i, 2]][k0], wFtmp[[i, 2]][\[Theta]], {C12, C22, C32}};
		\[Theta]tmp = VectorAngle[(wFtmp[[i, 1]][k] + wFtmp[[i, 2]][k]) / (wFtmp[[i, 1]][k0] + wFtmp[[i, 2]][k0]), {0, 0, 1}];
		wF1F2Inhtmp = setWave@{2w, wFtmp[[i, 1]][k] + wFtmp[[i, 2]][k], wFtmp[[i, 1]][k0] + wFtmp[[i, 2]][k0], \[Theta]tmp, {C13, C23, C33}};
		
		wB1B1Inhtmp = setWave@{2w, 2wBtmp[[i, 1]][k], 2wBtmp[[i, 1]][k0], wBtmp[[i, 1]][\[Theta]], {C14, C24, C34}};
		wB2B2Inhtmp = setWave@{2w, 2wBtmp[[i, 2]][k], 2wBtmp[[i, 2]][k0], wBtmp[[i, 2]][\[Theta]], {C15, C25, C35}};
		
		\[Theta]tmp = VectorAngle[(wBtmp[[i, 1]][k] + wBtmp[[i, 2]][k]) / (wBtmp[[i, 1]][k0] + wBtmp[[i, 2]][k0]), {0, 0, 1}];
		wB1B2Inhtmp = setWave@{2w, wBtmp[[i, 1]][k] + wBtmp[[i, 2]][k], wBtmp[[i, 1]][k0] + wBtmp[[i, 2]][k0], \[Theta]tmp, {C16, C26, C36}};
		
		If[(wFtmp[[i, 1]][k] + wBtmp[[i, 1]][k]) == 0, \[Theta]tmp = 0, 
		\[Theta]tmp = VectorAngle[(wFtmp[[i, 1]][k] + wBtmp[[i, 1]][k]) / (wFtmp[[i, 1]][k0] + wBtmp[[i, 1]][k0]), {0, 0, 1}]];
		wF1B1Inhtmp = setWave@{2w, wFtmp[[i, 1]][k] + wBtmp[[i, 1]][k], wFtmp[[i, 1]][k0] + wBtmp[[i, 1]][k0], \[Theta]tmp, {C17, C27, C37}};
		If[(wFtmp[[i, 2]][k] + wBtmp[[i, 2]][k]) == 0, \[Theta]tmp = 0, \[Theta]tmp = VectorAngle[(wFtmp[[i, 2]][k] + wBtmp[[i, 2]][k]) / (wFtmp[[i, 2]][k0] + wBtmp[[i, 2]][k0]), {0, 0, 1}]];
		wF2B2Inhtmp = setWave@{2w, wFtmp[[i, 2]][k] + wBtmp[[i, 2]][k], wFtmp[[i, 2]][k0] + wBtmp[[i, 2]][k0], \[Theta]tmp, {C18, C28, C38}};
		If[(wFtmp[[i, 1]][k] + wBtmp[[i, 2]][k]) == 0, \[Theta]tmp = 0, 
		\[Theta]tmp = VectorAngle[(wFtmp[[i, 1]][k] + wBtmp[[i, 2]][k]) / (wFtmp[[i, 1]][k0] + wBtmp[[i, 2]][k0]), {0, 0, 1}]];
		wF1B2Inhtmp = setWave@{2w, wFtmp[[i, 1]][k] + wBtmp[[i, 2]][k], wFtmp[[i, 1]][k0] + wBtmp[[i, 2]][k0], \[Theta]tmp, {C19, C29, C39}};
		If[(wFtmp[[i, 2]][k] + wBtmp[[i, 1]][k]) == 0, \[Theta]tmp = 0, \[Theta]tmp = VectorAngle[(wFtmp[[i, 2]][k] + wBtmp[[i, 1]][k]) / (wFtmp[[i, 2]][k0] + wBtmp[[i, 1]][k0]), {0, 0, 1}]];
		wF2B1Inhtmp = setWave@{2w, wFtmp[[i, 2]][k] + wBtmp[[i, 1]][k], wFtmp[[i, 2]][k0] + wBtmp[[i, 1]][k0], \[Theta]tmp, {C110, C210, C310}};
		
		(*consider both backward and standing waves*)
		solveInhom[mAll[[i + 1]], {wFtmp[[i, 1]], wFtmp[[i, 2]], wBtmp[[i, 1]], wBtmp[[i, 2]]}, {wF1F1Inhtmp, wF2F2Inhtmp, wF1F2Inhtmp, wB1B1Inhtmp, wB2B2Inhtmp, wB1B2Inhtmp, wF1B1Inhtmp, wF2B2Inhtmp, wF1B2Inhtmp, wF2B1Inhtmp}];
		AppendTo[wF1B1Inh, wF1B1Inhtmp];AppendTo[wF2B2Inh, wF2B2Inhtmp];AppendTo[wF1B2Inh, wF1B2Inhtmp];AppendTo[wF2B1Inh, wF2B1Inhtmp];
		AppendTo[wB1B1Inh, wB1B1Inhtmp];AppendTo[wB2B2Inh, wB2B2Inhtmp];AppendTo[wB1B2Inh, wB1B2Inhtmp];
		AppendTo[wF1F1Inh, wF1F1Inhtmp];AppendTo[wF2F2Inh, wF2F2Inhtmp];AppendTo[wF1F2Inh, wF1F2Inhtmp];
	];
	
	wFHomo = Thread[{wF1, wF2}];
	wBHomo = Thread[{wB1, wB2}];
	wFInh = Thread[{wF1F1Inh, wF2F2Inh, wF1F2Inh}];
	wBInh = Thread[{wB1B1Inh, wB2B2Inh, wB1B2Inh}];
	wSInh = Thread[{wF1B1Inh, wF2B2Inh, wF1B2Inh, wF2B1Inh}];
	
	If[flagBackward, 
		If[flagStandingWave, 
			wMed = Flatten/@Thread[{wFHomo, wBHomo, wFInh, wBInh, wSInh}];
			wInh = Flatten/@Thread[{wFInh, wBInh, wSInh}];
			, 
			wMed = Flatten/@Thread[{wFHomo, wBHomo, wFInh, wBInh}];
			wInh = Flatten/@Thread[{wFInh, wBInh}];
		];
		, 
		wMed = Flatten/@Thread[{wFHomo, wBHomo, wFInh}];
		wInh = wFInh;
	];
	
	thickness = Key[h]/@mAll[[2;; - 2]];
	
	If[(!flagHH)&&flagJK, 
		(*Solve layer by layer*)
		unknowns = Key[EE]/@{wR1, wR2, wF1[[1]], wF2[[1]]};
		unknowns = DeleteDuplicates@Cases[unknowns, _Symbol, Infinity];
		solveFresnel[{}, {wR1, wR2}, {wF1[[1]], wF2[[1]], wFInh[[1]]}, unknowns];(*top*)
		
		(*add phase shift*)
		wF1tmp = wF1[[1]];
		wF2tmp = wF2[[1]];
		wB1tmp = wB1[[1]];
		wB2tmp = wB2[[1]];
		{wF1F1Inhtmp, wF2F2Inhtmp, wF1F2Inhtmp} = wFInh[[1]];
		
		wF1tmp[EE] = wF1[[1]][EE] Exp[I wF1[[1]][k].({0, 0, 1}thickness[[1]])];
		wF2tmp[EE] = wF2[[1]][EE] Exp[I wF2[[1]][k].({0, 0, 1}thickness[[1]])];
		wB1tmp[EE] = wB1[[1]][EE] Exp[I wB1[[1]][k].({0, 0, 1}thickness[[1]])];
		wB2tmp[EE] = wB2[[1]][EE] Exp[I wB2[[1]][k].({0, 0, 1}thickness[[1]])];
		wF1F1Inhtmp[EE] = wFInh[[1]][[1]][EE] Exp[I wFInh[[1]][[1]][k].({0, 0, 1}thickness[[1]])];
		wF2F2Inhtmp[EE] = wFInh[[1]][[2]][EE] Exp[I wFInh[[1]][[2]][k].({0, 0, 1}thickness[[1]])];
		wF1F2Inhtmp[EE] = wFInh[[1]][[3]][EE] Exp[I wFInh[[1]][[3]][k].({0, 0, 1}thickness[[1]])];
		
		wF1[[1]] = wF1tmp;
		wF2[[1]] = wF2tmp;
		wB1[[1]] = wB1tmp;
		wB2[[1]] = wB2tmp;
		wFInh[[1]] = {wF1F1Inhtmp, wF2F2Inhtmp, wF1F2Inhtmp};
		
		For[i = 1, i<nM, i++, (*middle*)
			unknowns = Key[EE]/@{wB1[[i]], wB2[[i]], wF1[[i + 1]], wF2[[i + 1]]};
			unknowns = DeleteDuplicates@Cases[unknowns, _Symbol, Infinity];
			solveFresnel[{wF1tmp, wF2tmp, wF1F1Inhtmp, wF2F2Inhtmp, wF1F2Inhtmp}, {wB1[[i]], wB2[[i]]}, {wF1[[i + 1]], wF2[[i + 1]], wFInh[[i + 1]]}, unknowns];
			
			wF1tmp = wF1[[i + 1]];
			wF2tmp = wF2[[i + 1]];
			wB1tmp = wB1[[i + 1]];
			wB2tmp = wB2[[i + 1]];
			{wF1F1Inhtmp, wF2F2Inhtmp, wF1F2Inhtmp} = wFInh[[i + 1]];
			
			wF1tmp[EE] = wF1[[i + 1]][EE] Exp[I wF1[[i + 1]][k].({0, 0, 1}thickness[[i + 1]])];
			wF2tmp[EE] = wF2[[i + 1]][EE] Exp[I wF2[[i + 1]][k].({0, 0, 1}thickness[[i + 1]])];
			wB1tmp[EE] = wB1[[i + 1]][EE] Exp[I wB1[[i + 1]][k].({0, 0, 1}thickness[[i + 1]])];
			wB2tmp[EE] = wB2[[i + 1]][EE] Exp[I wB2[[i + 1]][k].({0, 0, 1}thickness[[i + 1]])];
			wF1F1Inhtmp[EE] = wFInh[[i + 1]][[1]][EE] Exp[I wFInh[[i + 1]][[1]][k].({0, 0, 1}thickness[[i + 1]])];
			wF2F2Inhtmp[EE] = wFInh[[i + 1]][[2]][EE] Exp[I wFInh[[i + 1]][[2]][k].({0, 0, 1}thickness[[i + 1]])];
			wF1F2Inhtmp[EE] = wFInh[[i + 1]][[3]][EE] Exp[I wFInh[[i + 1]][[3]][k].({0, 0, 1}thickness[[i + 1]])];
			
			wF1[[i + 1]] = wF1tmp;
			wF2[[i + 1]] = wF2tmp;
			wB1[[i + 1]] = wB1tmp;
			wB2[[i + 1]] = wB2tmp;
			wFInh[[i + 1]] = {wF1F1Inhtmp, wF2F2Inhtmp, wF1F2Inhtmp};
		];
		
		unknowns = Key[EE]/@{wB1[[nM]], wB2[[nM]], wT1, wT2};
		unknowns = DeleteDuplicates@Cases[unknowns, _Symbol, Infinity];
		solveFresnel[{wF1tmp, wF2tmp, wF1F1Inhtmp, wF2F2Inhtmp, wF1F2Inhtmp}, {wB1[[nM]], wB2[[nM]]}, {wT1, wT2}, unknowns];(*bottom*)
		wFHomo = Thread[{wF1, wF2}];
		wBHomo = Thread[{wB1, wB2}];
		wInh = wFInh;(*just for output*)
	];
	
	If[(!flagJK)&&flagHH, 
		(*Solve layer by layer*)
		
		(*Solve all waves at once*)
		wMed = Flatten/@Thread[{wFHomo, wBHomo, wFInh}];
		wInh = wFInh;
		unknowns = Join[Key[EE]/@{wR1, wR2}, Key[EE]/@Flatten@{wFHomo, wBHomo}, Key[EE]/@{wT1, wT2}];
		unknowns = DeleteDuplicates@Cases[unknowns, _Symbol, Infinity];
		solveFresnelN[{wR1, wR2}, wMed, {wT1, wT2}, thickness, unknowns];
		wFHomo = wMed[[All, 1;;2]];
		wBHomo = wMed[[All, 3;;4]];
		(*
		unknowns = Key[EE]/@{wR1, wR2, wF1[[1]], wF2[[1]]};
		unknowns = DeleteDuplicates@Cases[unknowns, _Symbol, Infinity];
		solveFresnel[{}, {wR1, wR2}, {wF1[[1]], wF2[[1]], wFInh[[1]]}, unknowns];(*top*)
		
		(*DO NOT add phase shift*)
		wF1tmp = wF1[[1]];
		wF2tmp = wF2[[1]];
		wB1tmp = wB1[[1]];
		wB2tmp = wB2[[1]];
		{wF1F1Inhtmp, wF2F2Inhtmp, wF1F2Inhtmp} = wFInh[[1]];
		
		For[i = 1, i<nM, i++, (*middle*)
			unknowns = Key[EE]/@{wB1[[i]], wB2[[i]], wF1[[i + 1]], wF2[[i + 1]]};
			unknowns = DeleteDuplicates@Cases[unknowns, _Symbol, Infinity];
			solveFresnel[{wF1tmp, wF2tmp, wF1F1Inhtmp, wF2F2Inhtmp, wF1F2Inhtmp}, {wB1[[i]], wB2[[i]]}, {wF1[[i + 1]], wF2[[i + 1]], wFInh[[i + 1]]}, unknowns];
			
			wF1tmp = wF1[[i + 1]];
			wF2tmp = wF2[[i + 1]];
			wB1tmp = wB1[[i + 1]];
			wB2tmp = wB2[[i + 1]];
			{wF1F1Inhtmp, wF2F2Inhtmp, wF1F2Inhtmp} = wFInh[[i + 1]];
		];
		
		unknowns = Key[EE]/@{wB1[[nM]], wB2[[nM]], wT1, wT2};
		unknowns = DeleteDuplicates@Cases[unknowns, _Symbol, Infinity];
		solveFresnel[{wF1tmp, wF2tmp, wF1F1Inhtmp, wF2F2Inhtmp, wF1F2Inhtmp}, {wB1[[nM]], wB2[[nM]]}, {wT1, wT2}, unknowns];(*bottom*)
		wFHomo = Thread[{wF1, wF2}];
		wBHomo = Thread[{wB1, wB2}];
		wInh = wFInh;(*just for output*)
		*)
	];
	
	If[(!flagJK)&&(!flagHH), 
		(*Solve all waves at once*)
		unknowns = Join[Key[EE]/@{wR1, wR2}, Key[EE]/@Flatten@{wFHomo, wBHomo}, Key[EE]/@{wT1, wT2}];
		unknowns = DeleteDuplicates@Cases[unknowns, _Symbol, Infinity];
		solveFresnelN[{wR1, wR2}, wMed, {wT1, wT2}, thickness, unknowns];
		wFHomo = wMed[[All, 1;;2]];
		wBHomo = wMed[[All, 3;;4]];
	];
	
	(*distinguish s and p from R1 and R2, T1 and T2*)
	(*no need to distinguish them for B and F waves cause they don't have to be s and p*)
	wRs = Cases[{wR1, wR2}, <|__, EE->{0, Except[0], 0}|>][[1]];
	wRp = DeleteCases[{wR1, wR2}, <|__, EE->{0, Except[0], 0}|>][[1]];
	wTs = Cases[{wT1, wT2}, <|__, EE->{0, Except[0], 0}|>][[1]];
	wTp = DeleteCases[{wT1, wT2}, <|__, EE->{0, Except[0], 0}|>][[1]];
	
	{sollinear, {{wRs, wRp}, {wTs, wTp}, wBHomo, wFHomo, wInh}}
];

