for Fresnel and Maker fringes

ClearAll[Fresnel, MF, MFandFresnel, SampleRotate];
Fresnel[mats_, thetatemp_, assumption_:0]:=Module[{wIncLocal, wavLLocal, wavNLLocal, tmpw1Local, tmpw2Local, rmpw1Local, rmpw2Local, rEtemp, tEtemp, m1, m2, m3}, 
	wIncLocal = setwInc[\[Omega]0, N@(thetatemp / 180 Pi), \[CapitalDelta]\[Delta], \[CurlyPhi], n0];extWave@wIncLocal;
	If[assumption == 0, 
		wavLLocal = f4L[mats, wIncLocal];
		, 
		If[assumption == 1||assumption == 2, 
			wavLLocal = f4L[mats, wIncLocal, True];
		]
	];
	{rmpw1Local, rmpw2Local} = wavLLocal[[1]]; 
	{tmpw1Local, tmpw2Local} = wavLLocal[[2]]; (*[[1]] is for reflected,  [[2]] is for transmitted*)
	extWave@rmpw1Local;extWave@rmpw2Local;extWave@tmpw1Local;extWave@tmpw2Local;
	
	rEtemp = (rmpw1Local[A] + rmpw2Local[A])[[1;;2]];
	tEtemp = (tmpw1Local[A] + tmpw2Local[A])[[1;;2]];
	
	{thetatemp, rEtemp[[1]] * Conjugate[rEtemp[[1]]], rEtemp[[2]] * Conjugate[rEtemp[[2]]], tEtemp[[1]] * Conjugate[tEtemp[[1]]], tEtemp[[2]] * Conjugate[tEtemp[[2]]]}
];
MF[mats_, thetatemp_, assumption_:0]:=Module[{wIncLocal, wavLLocal, wavNLLocal, tmpw1Local, tmpw2Local, tEboLocal, tEruiLocal, m1, m2, m3}, 
	wIncLocal = setwInc[\[Omega]0, N@(thetatemp / 180 Pi), \[CapitalDelta]\[Delta], \[CurlyPhi], n0];extWave@wIncLocal;
	If[assumption == 0, 
		flagJK = False;flagHH = False;
		{wavLLocal, wavNLLocal} = f4NL[mats, wIncLocal];
		, 
		If[assumption == 1, 
			flagBackward = False;
			flagStandingWave = False;
			flagJK = True;flagHH = False;
			{wavLLocal, wavNLLocal} = f4NL[mats, wIncLocal, True];
			, 
			If[assumption == 2, 
				flagBackward = False;
				flagStandingWave = False;
				flagJK = False;flagHH = True;
				{wavLLocal, wavNLLocal} = f4NL[mats, wIncLocal, True];
			];
		];
	];
	{tmpw1Local, tmpw2Local} = wavNLLocal[[2]]; (*[[1]] is for reflected,  [[2]] is for transmitted*)
	extWave@tmpw1Local;extWave@tmpw2Local;
	
	tEboLocal = (tmpw2Local[A] + tmpw1Local[A])[[1;;2]];
	tEruiLocal = {{Cos[\[Psi]], Sin[\[Psi]]}, { - Sin[\[Psi]], Cos[\[Psi]]}}. tEboLocal;
	
	{thetatemp, tEruiLocal[[1]] * Conjugate[tEruiLocal[[1]]], tEruiLocal[[2]] * Conjugate[tEruiLocal[[2]]]}
];

SetAttributes[SampleRotate, HoldAll];
SampleRotate[mats_, thetatemp_, rotatetemp_, rotatesteptemp_, assumption_:0, totalmats_, \[CapitalDelta]\[Delta]_, \[CurlyPhi]temp_, \[Psi]_]:=Module[{wIncLocal, wavLLocal, wavNLLocal, tmpw1Local, tmpw2Local, tEboLocal, tEruiLocal, tEruiLocal1, tEruiLocal2, m1, m2, m3, matstemp, rmpw1Local, rmpw2Local, rEboLocal, rEruiLocal, rEruiLocal1, rEruiLocal2, i}, 
	wIncLocal = setwInc[\[Omega]0, N@(thetatemp / 180 Pi), \[CapitalDelta]\[Delta], \[CurlyPhi], n0];
	extWave@wIncLocal;
	If[rotatetemp != 0, 
	For[i = 2, i<=(totalmats + 1), i = i + 1, 
		matstemp = mats[[i]];
		If [matstemp[[Key[orientation]]][[1]]  == 1,  matstemp[[Key[orientation]]][[1]]  =  2 ];
		matstemp[[Key[orientation]]][[3]][[1]]  =  Chop[(N[{{Cos[rotatesteptemp Degree],  - Sin[rotatesteptemp Degree], 0}, {Sin[rotatesteptemp Degree], Cos[rotatesteptemp Degree], 0}, {0, 0, 1}}.matstemp[[Key[orientation]]][[3]][[1]]])];
		
		matstemp[[Key[orientation]]][[3]][[2]]  =  Chop[(N[{{Cos[rotatesteptemp Degree],  - Sin[rotatesteptemp Degree], 0}, {Sin[rotatesteptemp Degree], Cos[rotatesteptemp Degree], 0}, {0, 0, 1}}.matstemp[[Key[orientation]]][[3]][[2]]])];
		
		matstemp[[Key[orientation]]][[3]][[3]]  =  Chop[(N[{{Cos[rotatesteptemp Degree],  - Sin[rotatesteptemp Degree], 0}, {Sin[rotatesteptemp Degree], Cos[rotatesteptemp Degree], 0}, {0, 0, 1}}.matstemp[[Key[orientation]]][[3]][[3]]])];
		
		hklConvert[matstemp];(*update the orientation*)
		extMater@matstemp;(*update the material*)
		mats[[i]] = matstemp;
		
	]];
	(*If [i == 2,  Print["angle = ", rotatetemp, "; ", mats[[2]]]];*)
	(*Print[rotatetemp, "   ", mats[[2]]];*)
	If[assumption == 0, 
		flagJK = False;flagHH = False;
		{wavLLocal, wavNLLocal} = f4NL[mats, wIncLocal];
		, 
		If[assumption == 1, 
			flagBackward = False;
			flagStandingWave = False;
			flagJK = True;flagHH = False;
			{wavLLocal, wavNLLocal} = f4NL[mats, wIncLocal, True];
			, 
			If[assumption == 2, 
				flagBackward = False;
				flagStandingWave = False;
				flagJK = False;flagHH = True;
				{wavLLocal, wavNLLocal} = f4NL[mats, wIncLocal, True];
			];
		];
	];
	{rmpw1Local, rmpw2Local} = wavNLLocal[[1]]; 
	{tmpw1Local, tmpw2Local} = wavNLLocal[[2]]; (*[[1]] is for reflected,  [[2]] is for transmitted*)
	extWave@rmpw1Local;extWave@rmpw2Local;
	extWave@tmpw1Local;extWave@tmpw2Local;
	
	rEboLocal = (rmpw2Local[A] + rmpw1Local[A])[[1;;2]];
	rEruiLocal = {{Cos[\[Psi]],  - Sin[\[Psi]]}, {Sin[\[Psi]], Cos[\[Psi]]}}. rEboLocal;
	(*rEruiLocal1 = {{Cos[\[Psi]],  - Sin[\[Psi]]}, {Sin[\[Psi]], Cos[\[Psi]]}}. rEboLocal;
	rEruiLocal2 = {{Cos[\[Psi] + Pi],  - Sin[\[Psi] + Pi]}, {Sin[\[Psi] + Pi], Cos[\[Psi] + Pi]}}. rEboLocal;*)
	
	tEboLocal = (tmpw2Local[A] + tmpw1Local[A])[[1;;2]];
	tEruiLocal = {{Cos[\[Psi]], Sin[\[Psi]]}, { - Sin[\[Psi]], Cos[\[Psi]]}}. tEboLocal;
	(*tEruiLocal1 = {{Cos[\[Psi]], Sin[\[Psi]]}, { - Sin[\[Psi]], Cos[\[Psi]]}}. tEboLocal;
	tEruiLocal2 = {{Cos[\[Psi] + Pi], Sin[\[Psi] + Pi]}, { - Sin[\[Psi] + Pi], Cos[\[Psi] + Pi]}}. tEboLocal;*)
	
	(*{rotatetemp, 
	Re[rEruiLocal1[[1]] * Conjugate[rEruiLocal1[[1]]]] + Re[rEruiLocal2[[1]] * Conjugate[rEruiLocal2[[1]]]], Re[rEruiLocal1[[2]] * Conjugate[rEruiLocal1[[2]]]] + Re[rEruiLocal2[[2]] * Conjugate[rEruiLocal2[[2]]]], Re[tEruiLocal1[[1]] * Conjugate[tEruiLocal1[[1]]]] + Re[tEruiLocal2[[1]] * Conjugate[tEruiLocal2[[1]]]], Re[tEruiLocal1[[2]] * Conjugate[tEruiLocal1[[2]]]] + Re[tEruiLocal2[[2]] * Conjugate[tEruiLocal2[[2]]]]}*)
	
	(*{rotatetemp , 
	Re[(rEruiLocal[[1]]/.\[CurlyPhi]->\[CurlyPhi]temp) * Conjugate[(rEruiLocal[[1]]/.\[CurlyPhi]->\[CurlyPhi]temp)]] + Re[(rEruiLocal[[1]]/.\[CurlyPhi]->(\[CurlyPhi]temp + Pi)) * Conjugate[(rEruiLocal[[1]]/.\[CurlyPhi]->(\[CurlyPhi]temp + Pi))]], 
	Re[(rEruiLocal[[2]]/.\[CurlyPhi]->\[CurlyPhi]temp) * Conjugate[(rEruiLocal[[2]]/.\[CurlyPhi]->\[CurlyPhi]temp)]] + Re[(rEruiLocal[[2]]/.\[CurlyPhi]->(\[CurlyPhi]temp + Pi)) * Conjugate[(rEruiLocal[[2]]/.\[CurlyPhi]->(\[CurlyPhi]temp + Pi))]], 
	Re[(tEruiLocal[[1]]/.\[CurlyPhi]->\[CurlyPhi]temp) * Conjugate[(tEruiLocal[[1]]/.\[CurlyPhi]->\[CurlyPhi]temp)]] + Re[(tEruiLocal[[1]]/.\[CurlyPhi]->(\[CurlyPhi]temp + Pi)) * Conjugate[(tEruiLocal[[1]]/.\[CurlyPhi]->(\[CurlyPhi]temp + Pi))]], 
	Re[(tEruiLocal[[2]]/.\[CurlyPhi]->\[CurlyPhi]temp) * Conjugate[(tEruiLocal[[2]]/.\[CurlyPhi]->\[CurlyPhi]temp)]] + Re[(tEruiLocal[[2]]/.\[CurlyPhi]->(\[CurlyPhi]temp + Pi)) * Conjugate[(tEruiLocal[[2]]/.\[CurlyPhi]->(\[CurlyPhi]temp + Pi))]]};*)
	
	(*{rotatetemp , 
	Re[(rEruiLocal[[1]]) * Conjugate[(rEruiLocal[[1]])]], 
