	{rotatetemp , 
	Re[(rEruiLocal[[1]]/.\[CurlyPhi]->\[CurlyPhi]temp) * Conjugate[(rEruiLocal[[1]])/.\[CurlyPhi]->\[CurlyPhi]temp]], 
